function publicScenario(q){if(!q)return null;const value=copy(q);value.stage=copy(stage(q));for(const key of['sourceAttendance','lastPositions','movement'])delete value[key];return value;}
function inspect(m,h){const s=h.systems?.dateAdventures??initial(),a=s.active,d=current(h),c=a?s.couples[a.coupleKey]:null;return{schemaVersion:VERSION,active:a?{dateId:a.dateId,personIds:copy(a.personIds),offers:d?.id===a.dateId?offers(m,h,s,d):[],scenario:publicScenario(a.scenario),partnerObservation:copy(a.partnerObservation??null),quietUntilMinute:a.quietUntilMinute,locations:copy(a.locations),available:d?.id===a.dateId&&together(m,d),reason:d?.id===a.dateId&&!together(m,d)?'Regroup the actual pair and finish their walk before choosing.':null}:null,cast:DATE_ADVENTURE_CAST.map(c=>({...copy(c),visits:s.cast[c.id]?.visits??0})),couple:c?{...copy(c),unlocks:c.unlocked.map(u=>({...copy(u),proposedHouseAction:proposal(h,c.personIds,u.id)}))}:null,history:copy(s.history),events:copy(s.events),homePractices:copy(s.homePractices),capabilities:{actualPair:true,fictionalCast:true,doubleDate:'Two existing actual date pairs, same venue, four explicit agreements; no spawn or forced admission',homePracticeAction:'dateHomeTogether',secondHumanPlayer:'Provided separately by the date control layer'},unsupported:['Authored fictional NPCs and prop cake are not population residents or edible inventory.','Digital gifts/designs/notebooks are metadata; no physical furniture, ingredients or ownership is created.','Destination and home plans require ordinary planner/action execution; no forced travel, return or date completion.','Custom scene animations and environmental meshes require the separate renderer; backend proves actual movement/actions/photos.']};}
function validate(m,h){const s=h.systems?.dateAdventures;if(!s)return true;check(s.schemaVersion===VERSION&&JSON.stringify(s).length<=cap&&s.events.length<=28&&s.history.length<=8&&s.receipts.length<=48&&s.homePractices.length<=16&&Object.keys(s.couples).length<=4&&new Set(s.receipts.map(r=>r.commandId)).size===s.receipts.length&&Number.isSafeInteger(s.nextId)&&s.nextId>=0,'Invalid bounded adventure checkpoint');for(const c of Object.values(s.couples)){check(c.personIds.length===2&&new Set(c.personIds).size===2&&c.unlocked.length<=8&&c.gifts.length<=4&&c.observations.length<=8&&c.stories.openingNight.chapter<=3,'Invalid retained adventure couple');c.personIds.forEach(id=>index(m,id));for(const u of c.unlocked)check(u.sourceAdventureId&&Number.isFinite(u.earnedMinute)&&u.earnedMinute<=m.minute&&Number.isInteger(u.practiceCount)&&u.practiceCount>=0,'Unlocks require completed adventure provenance');}const a=s.active;if(a){check(a.personIds.length===2&&pair(a.personIds)===a.coupleKey&&a.locations.length<=12&&Number.isFinite(a.quietUntilMinute),'Invalid active adventure session');a.personIds.forEach(id=>index(m,id));a.locations.forEach(validateDatePlace);const q=a.scenario;if(q){check(definition(q.scenarioId)&&pair(q.personIds)===a.coupleKey&&q.stages.length>=2&&q.stages.length<=8&&['active','completed','abandoned'].includes(q.status)&&Number.isInteger(q.stageIndex)&&q.stageIndex>=0&&q.stageIndex<=q.stages.length&&q.choices.length<=8&&q.evidence.length<=6&&Array.isArray(q.baselinePhotoIds)&&q.baselinePhotoIds.length<=32&&new Set(q.evidence.map(e=>e.id)).size===q.evidence.length&&Object.keys(q.sourceAttendance).length<=40&&Number.isFinite(q.readyMinute)&&q.readyMinute<=m.minute&&Number.isFinite(q.sharedMinutes)&&q.sharedMinutes>=0,'Invalid evidenced adventure');check(q.stages.every((st,i)=>['choice','evidence'].includes(st.type)&&st.status===(i<q.stageIndex?'completed':'pending')&&(i>=q.stageIndex||st.type==='choice'||typeof st.evidenceId==='string'))&&q.choices.length===q.stages.slice(0,q.stageIndex).filter(st=>st.type==='choice').length&&q.evidence.length===q.stages.slice(0,q.stageIndex).filter(st=>st.type==='evidence').length,'Adventure progress must match retained choices and distinct objective evidence');for(const v of Object.values(q.sourceAttendance))check(Number.isFinite(v)&&v>=0&&v<=1440,'Invalid actual adventure attendance');if(q.status==='completed')check(q.stageIndex===q.stages.length&&q.evidence.length>0&&q.outcome&&Number.isFinite(q.completedMinute)&&q.completedMinute<=m.minute,'Adventure completion requires actual evidence');}}for(const e of s.events)check(Number.isFinite(e.minute)&&e.minute<=m.minute&&e.personIds.length>=2&&e.personIds.length<=4&&e.text.length<=260,'Invalid adventure event');return true;}
export function createDateAdventureSystem(){return{id:'date-adventures',actions:DATE_ADVENTURE_HOME_ACTIONS,prepare,advance,command,inspect,validate,actionPlan:homeActionPlan,completeAction:homeCompletion};}
